import React from 'react'

class Cell extends React.Component {

    constructor(props) {
        super(props);

        this.state = {
            rowNum: props.rowNum,
            colNum: props.colNum,
            content: props.populator()
        }

        this.onClick = this.onClick.bind(this);
        this.reroll = this.reroll.bind(this);
    }

    onClick() {
        this.reroll();
    }

	birthdayLetter() {
		let n = 4 * this.state.rowNum + this.state.colNum;
        let ltr = 'お誕生日おめでとうございます！！'[n];
		console.log(this.state.rowNum, this.state.colNum, n, ltr);
		return ltr;
	}

    reroll() {
      this.setState({
          rowNum: this.state.rowNum,
          colNum: this.state.colNum,
          content: this.birthdayLetter()
      })
    }

    render() {
        return (
            <div id={
                    this.props.rowNum + "," + this.props.colNum
                }
                className="boardCell"
                    onClick={
                        this.onClick
                }>
                    {
                    this.state.content
                }
            </div>
        )
    }
}

export default Cell;
