import React from 'react';
import Cell from './Cell.jsx';

class Board extends React.Component {

    row(rowNum, nElements) {
        let cells = [];
        for (let i = 0; i < this.props.cols; i++) {
            cells.push (
                <Cell key={
                        rowNum + "," + i
                    }
                    rowNum={rowNum}
                    colNum={i}
                    populator={
                        this.props.populator
                    }/>
            )
        }

        return <div key={
                "row" + rowNum
            }
            className="boardRow">
            {cells}</div>;
    }

    buildBoard() {
        let rows = [];
        for (let i = 0; i < this.props.rows; i++) {
            rows.push(this.row(i, this.props.cols));
        }

        return rows;
    }

    render() {
        return (
            <section id="board" className="board">
                {
                this.buildBoard()
            } </section>
        )
    }
}

export default Board;
